import pathlib,json,hashlib
s=${JSON.stringify(s)}
for role in ['original-reader','revised-reader']:
    for ending in ['prompt.txt','manifest.json','settings.json','dispatch-receipt.json']:
        q=pathlib.Path(s)/(role+'-'+ending)
