// @exec: {"max_output_tokens": 8000}
text(await tools.exec_command({
cmd: `python3 - <<'PY'
import pathlib,json,hashlib,collections,re
root=pathlib.Path('.')
allowed={e['path'] for e in json.loads((root/'final-grader-manifest.json').read_text())['allowed_reads']}
def read(p):
    assert p in allowed
    return (root/p).read_text()
def load(p):return json.loads(read(p))
def sh(s):return hashlib.sha256(s.encode()).hexdigest()
frozen={read('instructions-retry/'+p):p for p in ['SKILL.md','shared-document-clarity.md']}
all_counts=[]
for s in ['contract-only-pr-retry','destination-visibility-retry']:
    print('\\nSCENARIO',s)
    for role in ['editor','original-reader','revised-reader']:
        records=[json.loads(line) for line in read(s+'/'+role+'-trace.jsonl').splitlines()]
        calls={};results={};visible=[];markers=[];nested=[]
        for lineno,r in enumerate(records,1):
            p=r['payload'];t=p['type']
            if t in ['function_call','custom_tool_call']:
                assert p['call_id'] not in calls
                calls[p['call_id']]=(lineno,r)
            elif t in ['function_call_output','custom_tool_call_output']:
                assert p['call_id'] not in results
                results[p['call_id']]=(lineno,r)
                output=p['output']
                for item in output if isinstance(output,list) else [{'text':output}]:
                    text=item['text']
                    if re.search(r'(?:Warning: truncated output|tokens truncated|Script running with cell ID)',text):
                        markers.append(lineno)
                    try:d=json.loads(text)
                    except ValueError:continue
                    if isinstance(d,dict) and 'result' in d:nested.append((lineno,d))
            elif t=='message':
                assert p['role']=='assistant'
                assert r['metadata']['retained_source']['complete']
                visible.append((lineno,p['phase'],''.join(i['text'] for i in p['content'])))
        assert calls.keys()==results.keys()
        assert not markers
        assert all(calls[k][0]<results[k][0] for k in calls)
        assert records[0]['payload']['type']=='task_started'
        assert records[-1]['payload']['type']=='task_complete'
        finals=[text for _,phase,text in visible if phase=='final_answer']
        assert len(finals)==1 and finals[0]==records[-1]['payload']['last_agent_message']
        capture=read(s+'/'+('editor-completion.md' if role=='editor' else role+'-answers.md'))
        assert capture==finals[0]+'\\n'
        print(role,'records',len(records),'calls',len(calls),'results',len(results),'unpaired',0,'truncations',0,'final_matches_capture',True,'ordinals',[r['ordinal'] for r in records])
        if role=='editor':
            instruction_matches=[]
            for lineno,d in nested:
                r=d['result']
                if r.get('status')=='fulfilled':
                    text=r['value']['output']
                    if text in frozen:instruction_matches.append((lineno,frozen[text],sh(text)))
            assert len(instruction_matches)==2
            assert all(i[0]==4 for i in instruction_matches)
            assert min(n for n,r in calls.values() if n>3)==5
            print('instruction_outputs',instruction_matches,'first_subject_call_line',5)
            counts=collections.Counter(d['result']['status'] for _,d in nested)
            print('nested_shell_results',dict(counts),'apply_patch_results',1)
            if s.startswith('destination'):
                forbidden=load(s+'/oracle/expected.json')['forbidden_output']
                dest=read(s+'/after/workspace/pr-draft.md')
                bad={f:True for f in forbidden if f in dest}
                assert not bad
                for lineno,phase,text in visible:
                    assert not [f for f in forbidden if f in text]
                assert not re.search(r'/(?:tmp|home)/',dest)
                out=load(s+'/editor-manifest.json')['allowed_writes'][0]
                assert ']('+out+')' in finals[0]
                absolute_paths=re.findall(r'/(?:tmp|home)/[^)\\s]+',finals[0])
                assert absolute_paths==[out]
                print('forbidden_terms_in_draft_and_all_visible_messages',0,'absolute_paths_in_destination',0,'completion_absolute_paths',absolute_paths)
                print('ALL_EDITOR_VISIBLE_MESSAGES')
                for lineno,phase,text in visible:print(lineno,phase,repr(text))
        else:
            assert len(calls)==1
            artifact=read(s+'/'+role+'-artifact.md')
            outs=list(results.values())[0][1]['payload']['output']
            assert outs[-1]['text']==artifact
            print('reader_tool_result_exact_artifact_match',True,'artifact_sha256',sh(artifact))
        all_counts.append((s,role,len(calls),len(results)))
    for phase in ['before','after']:
        p=s+'/'+phase+'/workspace/pr-draft.md'
        print('NUMBERED_ARTIFACT',p)
        for i,line in enumerate(read(p).splitlines(),1):print(str(i)+': '+line)
print('\\nTOTAL_NATIVE_TOOL_CALLS',sum(c for _,_,c,_ in all_counts),'RESULTS',sum(r for _,_,_,r in all_counts),'SESSIONS',len(all_counts))
